function S({registerIndicator:x,sourceValues:A,nulls:N}){x({id:"oa-tema",name:"Triple Exponential Moving Average (TEMA)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"tema",type:"line",title:"TEMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(r,p){const k=Math.max(1,Math.floor(Number(p.period)||10)),v=A(r,p.source??"close"),l=2/(k+1),s=l,i=l,E=1-l,w=1-s,I=1-i;let m=1,d=1,f=1,y=!0,o=0,e=0,t=0;const b=new Array(r.length).fill(NaN);for(let c=0;c<r.length;c++){const h=v[c];if(!Number.isFinite(h))continue;o=l*(h-o)+o;let n,a,u;if(y){m*=E,d*=w,f*=I;const M=1-m,T=1-d,g=1-f;if(M===0||T===0||g===0)continue;const F=1/M,P=1/T,R=1/g;n=o*F,e=s*(n-e)+e,a=e*P,t=i*(a-t)+t,u=t*R,y=m>1e-10}else n=o,e=s*(n-e)+e,a=e,t=i*(a-t)+t,u=t;b[c]=3*n-3*a+u}return{tema:N(b)}}})}export{S as default};
